/**
 * Msg is the write side of the syndication layer: onboard an investor, open a
 * deal, commit to it, close or abort it, distribute what comes back, and sell a
 * position on.
 */
export interface Msg {
  /** UpdateParams sets the platform-wide ceilings. Governance only. */
  UpdateParams(request: MsgUpdateParams): Promise<MsgUpdateParamsResponse>;
  /** RegisterOperator admits a platform operator. Governance only. */
  RegisterOperator(request: MsgRegisterOperator): Promise<MsgRegisterOperatorResponse>;
  /** OnboardInvestor records that an operator has completed KYC/AML on somebody. */
  OnboardInvestor(request: MsgOnboardInvestor): Promise<MsgOnboardInvestorResponse>;
  /** OpenDeal puts an allocation in front of the investor base. */
  OpenDeal(request: MsgOpenDeal): Promise<MsgOpenDealResponse>;
  /** Commit escrows an investor's cheque against a deal. */
  Commit(request: MsgCommit): Promise<MsgCommitResponse>;
  /**
   * WithdrawCommitment takes it back, which is only possible while the deal is
   * open.
   */
  WithdrawCommitment(request: MsgWithdrawCommitment): Promise<MsgWithdrawCommitmentResponse>;
  /** CloseDeal funds the company and issues the tokens. */
  CloseDeal(request: MsgCloseDeal): Promise<MsgCloseDealResponse>;
  /** AbortDeal refunds everybody in full. */
  AbortDeal(request: MsgAbortDeal): Promise<MsgAbortDealResponse>;
  /** Distribute pays a dividend or exit proceeds into the deal, pro-rata. */
  Distribute(request: MsgDistribute): Promise<MsgDistributeResponse>;
  /** Claim withdraws what a holder has accrued. */
  Claim(request: MsgClaim): Promise<MsgClaimResponse>;
  /** List offers part of a position for sale, openly or to a named buyer. */
  List(request: MsgList): Promise<MsgListResponse>;
  /** CancelListing withdraws an offer. */
  CancelListing(request: MsgCancelListing): Promise<MsgCancelListingResponse>;
  /** Buy fills a listing: settlement one way, tokens the other, in one block. */
  Buy(request: MsgBuy): Promise<MsgBuyResponse>;
  /**
   * AttachDocument records the hash of a paper the deal depends on. Never the
   * paper itself.
   */
  AttachDocument(request: MsgAttachDocument): Promise<MsgAttachDocumentResponse>;
}

export const MsgServiceName = "blockchain.syndicate.v1.Msg";
